#include <stdio.h>
#include <math.h>

#define MAX_ROPE 100
#define EPS 1e-9

double xs[MAX_ROPE], ls[MAX_ROPE];
int n;

// Check if balloon at height h is feasible
int feasible(double h) {
    // The balloon is at (0, h). For each rope i anchored at (xi, 0) with length li,
    // we need sqrt(xi^2 + h^2) <= li.
    // Since ropes cannot cross, the ordering of anchors by x must correspond to ordering
    // of rope lengths. But the problem says no two ropes cross, which is automatically
    // satisfied if we assign anchors in order and the balloon is at a single point.
    // However, we must check that each rope can reach the balloon.
    for (int i = 0; i < n; i++) {
        double dist = sqrt(xs[i] * xs[i] + h * h);
        if (dist > ls[i] + EPS) return 0;
    }
    return 1;
}

