        }
        // Binary search on height
        double lo = 0.0, hi = 1e9; // hi is large enough
        // First find a feasible hi
        while (!feasible(hi) && hi < 1e12) hi *= 2;
        // Binary search
        for (int iter = 0; iter < 80; iter++) {
            double mid = (lo + hi) / 2.0;
            if (feasible(mid)) {
                lo = mid;
