int main() {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        double ax[100], ay[100], L[100];
        for (int i = 0; i < n; i++) {
            scanf("%lf %lf %lf", &ax[i], &ay[i], &L[i]);
        }

        double x = 0, y = 0;
        double step = 1.0;

        for (int iter = 0; iter < 100000; iter++) {
            // Find minimum f value and which rope achieves it
            double minval = 1e18;
            int minidx = 0;
            for (int i = 0; i < n; i++) {
                double v = L[i]*L[i] - (x-ax[i])*(x-ax[i]) - (y-ay[i])*(y-ay[i]);
                if (v < minval) { minval = v; minidx = i; }
            }
            // Gradient direction: (-2(x-ax[minidx]), -2(y-ay[minidx]))
            // which points toward anchor
            double gx = -(x - ax[minidx]);
            double gy = -(y - ay[minidx]);
            double glen = sqrt(gx*gx + gy*gy);
            if (glen < 1e-12) { step *= 0.5; continue; }
            gx /= glen; gy /= glen;

            double nx = x + step * gx;
            double ny = y + step * gy;

            double newmin = 1e18;
            for (int i = 0; i < n; i++) {
                double v = L[i]*L[i] - (nx-ax[i])*(nx-ax[i]) - (ny-ay[i])*(ny-ay[i]);
                if (v < newmin) newmin = v;
            }

            if (newmin > minval) { x = nx; y = ny; }
            else step *= 0.5;

            if (step < 1e-9) break;
        }

        double maxz2 = 1e18;
        for (int i = 0; i < n; i++) {
            double v = L[i]*L[i] - (x-ax[i])*(x-ax[i]) - (y-ay[i])*(y-ay[i]);
            if (v < maxz2) maxz2 = v;
        }
        if (maxz2 < 0) maxz2 = 0;
        printf("%.5f\n", sqrt(maxz2));
    }
    return 0;
}

