typedef struct {
    double x, l;
} Rope;

int cmp_rope(const void *a, const void *b) {
    double xa = ((const Rope*)a)->x;
    double xb = ((const Rope*)b)->x;
    if (xa < xb) return -1;
    if (xa > xb) return 1;
    return 0;
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        Rope *r = (Rope*)malloc(sizeof(Rope) * n);
        for (int i = 0; i < n; i++) {
            scanf("%lf %lf", &r[i].x, &r[i].l);
        }

        qsort(r, n, sizeof(Rope), cmp_rope);

        double left = -1e100, right = 1e100;
        int possible = 1;

        for (int i = 0; i < n; i++) {
            if (r[i].l + 1e-12 < fabs(r[i].x)) {
                possible = 0;
                break;
            }
            double dx = sqrt(fmax(0.0, r[i].l * r[i].l - r[i].x * r[i].x));
            double li = -dx;
            double ri = dx;

            if (li > left) left = li;
            if (ri < right) right = ri;
        }

        if (!possible || left > right + 1e-12) {
            printf("0.00000\n");
        } else {
            double ans = right;
            if (ans < 0) ans = 0;
            printf("%.5f\n", ans);
        }

        free(r);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Rope {
    double x;      // anchor x-coordinate
    double len;    // rope length
};

double solve(vector<Rope>& ropes) {
    int n = ropes.size();

    // For each rope, the maximum height is determined by:
    // h^2 + x^2 = len^2 (Pythagorean theorem)
    // h = sqrt(len^2 - x^2) if the balloon goes straight up
    // But due to multiple ropes, we need to find the minimum possible height
    // that satisfies all constraints

    // The balloon can move in 3D space, but since all anchors are on the ground
    // and ropes are straight lines, the maximum height is determined by
    // the intersection of spheres centered at each anchor

    // Binary search on height
    double left = 0, right = 1e9;

    // Find upper bound
    for (auto& rope : ropes) {
        right = min(right, rope.len);
    }

    for (int iter = 0; iter < 100; iter++) {
        double mid = (left + right) / 2;
        bool possible = true;

        // Check if it's possible to be at height mid
        // At height mid, the balloon must be within reach of all ropes
        // For each rope, the horizontal distance from the anchor must be
        // <= sqrt(len^2 - mid^2)

        double min_x = -1e9, max_x = 1e9;

        for (auto& rope : ropes) {
            double max_horizontal = sqrt(rope.len * rope.len - mid * mid);

            // The balloon must be within this horizontal distance from the anchor
            // So x must satisfy: |x - anchor_x| <= max_horizontal
            double left_bound = rope.x - max_horizontal;
            double right_bound = rope.x + max_horizontal;

            min_x = max(min_x, left_bound);
            max_x = min(max_x, right_bound);

            if (min_x > max_x) {
                possible = false;
                break;
            }
        }

        if (possible) {
            left = mid;
        } else {
            right = mid;
        }
    }

    return left;
}

