#include <bits/stdc++.h>
using namespace std;

struct Rope {
    double x, l;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cout.setf(ios::fixed);
    cout << setprecision(10);

    while (cin >> n && n) {
        vector<Rope> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i].x >> a[i].l;

        // Sort anchors by x-coordinate.
        sort(a.begin(), a.end(), [](const Rope& p, const Rope& q) {
            return p.x < q.x;
        });

        // Feasibility test for a given height h.
        auto feasible = [&](double h) -> bool {
            double L = -1e100, R = 1e100;

            for (int i = 0; i < n; ++i) {
                if (a[i].l < h) return false;

                double dx2 = a[i].l * a[i].l - h * h;
                if (dx2 < 0) return false;
                double dx = sqrt(max(0.0, dx2));

                double li = a[i].x - dx;
                double ri = a[i].x + dx;

                L = max(L, li);
                R = min(R, ri);
            }

            if (L > R) return false;

            // To avoid rope crossings, balloon's x-coordinate must preserve
            // the order of anchors around x=0:
            // for anchors left of 0, balloon x must be >= their x;
            // for anchors right of 0, balloon x must be <= their x.
            double low = -1e100, high = 1e100;
            for (int i = 0; i < n; ++i) {
                if (a[i].x < 0) low = max(low, a[i].x);
                if (a[i].x > 0) high = min(high, a[i].x);
            }

            L = max(L, low);
            R = min(R, high);

            return L <= R;
        };

        // Upper bound: cannot exceed any rope length.
        double hi = a[0].l;
        for (int i = 1; i < n; ++i) hi = min(hi, a[i].l);
        double lo = 0.0;

        for (int it = 0; it < 100; ++it) {
            double mid = (lo + hi) * 0.5;
            if (feasible(mid)) lo = mid;
            else hi = mid;
        }

        cout << lo << "\n";
    }

    return 0;
}

