public class Main {
    static class Rope {
        double x, len;
        Rope(double x, double len) {
            this.x = x;
            this.len = len;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        while ((line = br.readLine()) != null && !line.isEmpty()) {
            int n = Integer.parseInt(line.trim());
            if (n == 0) break;

            Rope[] ropes = new Rope[n];
            for (int i = 0; i < n; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                double x = Double.parseDouble(st.nextToken());
                double len = Double.parseDouble(st.nextToken());
                ropes[i] = new Rope(x, len);
            }

            double result = solve(ropes);
            System.out.printf("%.6f%n", result);
        }
    }

    static double solve(Rope[] ropes) {
        int n = ropes.length;
        // Sort ropes by x coordinate
        Arrays.sort(ropes, (a, b) -> Double.compare(a.x, b.x));

        // Binary search for maximum height
        double low = 0, high = 1e9;
        for (int iter = 0; iter < 100; iter++) {
            double mid = (low + high) / 2;
            if (canReachHeight(ropes, mid)) {
                low = mid;
            } else {
                high = mid;
            }
        }
        return low;
    }

    static boolean canReachHeight(Rope[] ropes, double h) {
        int n = ropes.length;

        // For each rope, the balloon must be within distance len from anchor
        // At height h, the balloon can be at x where |x - anchor_x| <= sqrt(len^2 - h^2)
        // So the reachable interval for each rope is [anchor_x - d, anchor_x + d]
        // where d = sqrt(len^2 - h^2) if len >= h, otherwise impossible

        double[] left = new double[n];
        double[] right = new double[n];

        for (int i = 0; i < n; i++) {
            if (ropes[i].len < h) return false;
            double d = Math.sqrt(ropes[i].len * ropes[i].len - h * h);
            left[i] = ropes[i].x - d;
            right[i] = ropes[i].x + d;
        }

        // Check if there exists a point that lies in all intervals
        double maxLeft = left[0];
        double minRight = right[0];
        for (int i = 1; i < n; i++) {
            maxLeft = Math.max(maxLeft, left[i]);
            minRight = Math.min(minRight, right[i]);
            if (maxLeft > minRight + 1e-12) return false;
        }
        return true;
    }
}

