public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            double[] ax = new double[n], ay = new double[n], L = new double[n];
            for (int i = 0; i < n; i++) {
                ax[i] = sc.nextDouble(); ay[i] = sc.nextDouble(); L[i] = sc.nextDouble();
            }
            // Binary search on h
            double lo = 0, hi = Arrays.stream(L).max().getAsDouble();
            for (int iter = 0; iter < 100; iter++) {
                double mid = (lo + hi) / 2;
                if (feasible(ax, ay, L, mid, n)) lo = mid;
                else hi = mid;
            }
            System.out.printf("%.5f%n", lo);
        }
    }

    static boolean feasible(double[] ax, double[] ay, double[] L, double h, int n) {
        double[] r2 = new double[n];
        for (int i = 0; i < n; i++) {
            r2[i] = L[i]*L[i] - h*h;
            if (r2[i] < 0) return false;
        }
        // Find point minimizing sum max(0, dist - sqrt(r2))^2
        double x = 0, y = 0;
        double step = Arrays.stream(L).max().getAsDouble();
        for (int iter = 0; iter < 100000; iter++) {
            double gx = 0, gy = 0;
            for (int i = 0; i < n; i++) {
                double dx = x - ax[i], dy = y - ay[i];
                double dist = Math.sqrt(dx*dx + dy*dy);
                double ri = Math.sqrt(r2[i]);
                if (dist > ri) { gx += (dist-ri)*dx/dist; gy += (dist-ri)*dy/dist; }
            }
            if (gx*gx+gy*gy < 1e-18) break;
            x -= step*gx; y -= step*gy;
            step *= 0.999;
        }
        for (int i = 0; i < n; i++) {
            double dx=x-ax[i],dy=y-ay[i];
            if (dx*dx+dy*dy > r2[i]+1e-6) return false;
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    static class Rope {
        double x, l;
        Rope(double x, double l) {
            this.x = x;
            this.l = l;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first;
        StringBuilder out = new StringBuilder();

        while ((first = fs.next()) != null) {
            int n = Integer.parseInt(first);
            if (n == 0) break;

            Rope[] ropes = new Rope[n];
            for (int i = 0; i < n; i++) {
                double x = fs.nextDouble();
                double l = fs.nextDouble();
                ropes[i] = new Rope(x, l);
            }

            Arrays.sort(ropes, Comparator.comparingDouble(a -> a.x));

            double leftBound = -1e100;
            double rightBound = 1e100;

            boolean impossible = false;

            for (int i = 0; i < n; i++) {
                if (ropes[i].l + 1e-12 < Math.abs(ropes[i].x)) {
                    impossible = true;
                    break;
                }
                double dx = Math.sqrt(Math.max(0.0, ropes[i].l * ropes[i].l - ropes[i].x * ropes[i].x));
                double li = ropes[i].x - dx;
                double ri = ropes[i].x + dx;

                // Non-crossing with anchors sorted by x means balloon x-position must be nondecreasing
                // with respect to anchor order; hence it must lie in the intersection of all reachable intervals.
                leftBound = Math.max(leftBound, li);
                rightBound = Math.min(rightBound, ri);
            }

            double ans;
            if (impossible || leftBound > rightBound + 1e-12) {
                ans = 0.0;
            } else {
                // For a fixed balloon x, feasible height is min_i sqrt(l_i^2 - (x-a_i)^2).
                // We maximize this over x in the common feasible interval.
                // Since f_i(x)^2 = l_i^2 - (x-a_i)^2 is concave, the minimum of concave functions is unimodal enough
                // for ternary search on this problem's constraints.
                double lo = leftBound, hi = rightBound;
                for (int it = 0; it < 200; it++) {
                    double m1 = (2 * lo + hi) / 3.0;
                    double m2 = (lo + 2 * hi) / 3.0;
                    double h1 = feasibleHeight(ropes, m1);
                    double h2 = feasibleHeight(ropes, m2);
                    if (h1 < h2) lo = m1;
                    else hi = m2;
                }
                ans = feasibleHeight(ropes, (lo + hi) / 2.0);
                if (ans < 0) ans = 0.0;
            }

            out.append(String.format(Locale.US, "%.10f%n", ans));
        }

        System.out.print(out.toString());
    }

    static double feasibleHeight(Rope[] ropes, double x) {
        double best = Double.POSITIVE_INFINITY;
        for (Rope r : ropes) {
            double d = r.l * r.l - (x - r.x) * (x - r.x);
            if (d < 0) return -1;
            best = Math.min(best, Math.sqrt(Math.max(0.0, d)));
        }
        return best;
    }
}

import sys
from scipy.optimize import minimize
import numpy as np

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    while idx < len(input_data):
        n = int(input_data[idx]); idx += 1
        if n == 0:
            break
        anchors = []
        for _ in range(n):
            ax, ay, L = float(input_data[idx]), float(input_data[idx+1]), float(input_data[idx+2])
            idx += 3
            anchors.append((ax, ay, L))

        def feasible(h):
            # Check if intersection of circles (x-ax)^2+(y-ay)^2 <= L^2-h^2 is non-empty
            radii_sq = [L*L - h*h for (ax,ay,L) in anchors]
            if any(r < -1e-9 for r in radii_sq):
                return False
            def obj(p):
                x, y = p
                return max((x-ax)**2+(y-ay)**2 - max(0,r) for (ax,ay,_),r in zip(anchors,radii_sq))
            res = minimize(obj, [0,0], method='Nelder-Mead', options={'xatol':1e-9,'fatol':1e-9,'maxiter':10000})
            return res.fun <= 1e-6

        lo, hi = 0.0, max(L for _,_,L in anchors)
        for _ in range(100):
            mid = (lo+hi)/2
            if feasible(mid):
                lo = mid
            else:
                hi = mid
        print(f"{lo:.5f}")

solve()
